import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.BpFM782D.js";const p=JSON.parse('{"title":"release","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/release.md","filePath":"en/skills/release.md"}'),r={name:"en/skills/release.md"};function s(l,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="release" tabindex="-1">release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;release&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>release</td></tr><tr><td>Description</td><td>Use when the user says &quot;release&quot;, &quot;publish&quot;, &quot;bump version&quot;, or wants to publish a new version to npm. Automates version bump, commit, push, tag, and CI-triggered publish.</td></tr><tr><td>Source Directory</td><td><code>skills/release/</code></td></tr></tbody></table><hr><h1 id="release-1" tabindex="-1">Release <a class="header-anchor" href="#release-1" aria-label="Permalink to &quot;Release&quot;">​</a></h1><p>Bump version, commit, push, tag — let CI publish.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ul><li>/release — Auto-detect bump type from commits since last tag</li><li>/release patch — Force patch bump (1.2.3 to 1.2.4)</li><li>/release minor — Force minor bump (1.2.3 to 1.3.0)</li><li>/release major — Force major bump (1.2.3 to 2.0.0)</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-determine-bump-type" tabindex="-1">1. Determine bump type <a class="header-anchor" href="#_1-determine-bump-type" aria-label="Permalink to &quot;1. Determine bump type&quot;">​</a></h3><p>If no argument given, auto-detect from commits since last tag. Run git log to see commit messages since the last tag.</p><p>Bump rules:</p><ul><li>If any commit starts with &quot;feat:&quot; — bump <strong>minor</strong></li><li>If only fix/chore/docs/refactor/perf/ci/test commits — bump <strong>patch</strong></li><li>If &quot;BREAKING CHANGE&quot; in any commit body — bump <strong>major</strong></li></ul><h3 id="_2-bump-version-in-package-json" tabindex="-1">2. Bump version in package.json <a class="header-anchor" href="#_2-bump-version-in-package-json" aria-label="Permalink to &quot;2. Bump version in package.json&quot;">​</a></h3><p>Read current version, compute new version. Edit package.json only.</p><h3 id="_3-update-changelog-md-mandatory-if-file-exists" tabindex="-1">3. Update CHANGELOG.md (MANDATORY if file exists) <a class="header-anchor" href="#_3-update-changelog-md-mandatory-if-file-exists" aria-label="Permalink to &quot;3. Update CHANGELOG.md (MANDATORY if file exists)&quot;">​</a></h3><p><strong>You MUST perform this step. Do NOT skip it.</strong></p><ol><li>Check if <code>CHANGELOG.md</code> exists in the repo root — run <code>ls CHANGELOG.md</code></li><li>If it exists, you MUST update it: a. Read the full content of <code>CHANGELOG.md</code> b. Run <code>git log --oneline &amp;lt;last-tag&gt;..HEAD</code> to collect all commits since the last tag c. Use the Edit tool to insert a new version section <strong>immediately after the file header</strong> (after the <code>格式基於...</code> line or equivalent intro), <strong>before</strong> any existing <code>## [</code> section d. Format following Keep a Changelog: <ul><li><code>## [X.Y.Z] - YYYY-MM-DD</code></li><li>Group by type: <code>### Added</code> (feat), <code>### Fixed</code> (fix), <code>### Changed</code> (refactor/chore/perf), <code>### Removed</code></li><li>Use commit description (strip type prefix) as bullet text</li><li>Match the language of existing entries</li></ul></li><li>If <code>CHANGELOG.md</code> does not exist, skip this step</li></ol><h3 id="_4-commit-and-push" tabindex="-1">4. Commit and push <a class="header-anchor" href="#_4-commit-and-push" aria-label="Permalink to &quot;4. Commit and push&quot;">​</a></h3><p>Stage package.json and CHANGELOG.md (if updated), commit with message &quot;chore: bump version to X.Y.Z&quot;, then push.</p><h3 id="_5-tag-and-push-tag" tabindex="-1">5. Tag and push tag <a class="header-anchor" href="#_5-tag-and-push-tag" aria-label="Permalink to &quot;5. Tag and push tag&quot;">​</a></h3><p>CRITICAL: Tag AFTER push so CI gets the correct package.json.</p><p>Create tag vX.Y.Z, then push the tag to origin.</p><h3 id="_6-report" tabindex="-1">6. Report <a class="header-anchor" href="#_6-report" aria-label="Permalink to &quot;6. Report&quot;">​</a></h3><p>Print summary with the new version, commit hash, tag name, and note that CI will publish automatically.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Never run npm publish locally — CI handles it</li><li>Never tag before pushing the version bump commit</li><li>Never amend or force-push tags that CI already processed</li><li>If no feat or fix commits found, ask user before proceeding</li></ul>',26)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
